async function driveDialog(prefer) {
  for (let i = 0; i < 40; i++) {
    const d = sdk.getDialog();
    if (!d.isOpen) return 'closed';
    const opts = d.options;
    if (opts.length > 1) {
      let choice = null;
      for (const p of (prefer || [])) {
        const m = opts.find(o => p.test(o.text));
        if (m) { choice = m; break; }
      }
      if (!choice) choice = opts[opts.length - 1];
      await sdk.sendClickDialog(choice.index);
    } else if (opts.length === 1) {
      await sdk.sendClickDialog(0);
    } else {
      await sdk.sendClickDialog(0);
    }
    await sdk.waitForTicks(3);
  }
  return 'loop-limit';
}

