const xp0 = xp;
let times = [];
while (Date.now() < end) {
  const s0 = Date.now();
  const chop = await bot.chopTree();
  const t1 = Date.now();
  const burn = await bot.burnLogs();
  const t2 = Date.now();
  if (burn?.success) { burns++; times.push({c: t1-s0, b: t2-t1}); }
  else if (burn) console.log('burn fail:', JSON.stringify(burn).slice(0,120));
  if (!chop?.success) console.log('chop fail:', JSON.stringify(chop).slice(0,120));
}
const avg = (arr,f) => arr.length? Math.round(arr.reduce((a,x)=>a+x[f],0)/arr.length) : 0;
return {
  burns, xpGained: sdk.getSkillXp('Firemaking')-xp0,
  avgChopMs: avg(times,'c'), avgBurnMs: avg(times,'b'),
  fmLevel: sdk.getSkill('Firemaking').level, wcLevel: sdk.getSkill('Woodcutting').level,
  elapsedMin: (Date.now()-start)/60000
};

